dd161c04-ef97-46da-b3ae-6e64819d12f9	Call to Action	Final conversion section	<section class="cta-section" data-component="call-to-action">\n    <div class="cta-container">\n        <h2>{{.headline}}</h2>\n        {{if .subheadline}}<p class="cta-subtitle">{{.subheadline}}</p>{{end}}\n        <div class="cta-buttons">\n            {{if .primary_cta}}\n            <a href="{{.primary_cta_url}}" class="cta-btn cta-btn-primary">{{.primary_cta}}</a>\n            {{end}}\n            {{if .secondary_cta}}\n            <a href="{{.secondary_cta_url}}" class="cta-btn cta-btn-secondary">{{.secondary_cta}}</a>\n            {{end}}\n        </div>\n    </div>\n</section>\n<style>\n.cta-section {\n    padding: var(--spacing-section, 5rem 2rem);\n    background: var(--color-primary, #1a1a2e);\n    color: var(--color-white, #fff);\n    text-align: center;\n\n    /* Dark section context */\n    --section-text: rgba(255,255,255,0.9);\n    --section-text-muted: rgba(255,255,255,0.85);\n    --section-heading: #ffffff;\n    --section-surface: rgba(255,255,255,0.05);\n    --section-border: rgba(255,255,255,0.2);\n}\n.cta-container {\n    max-width: 800px;\n    margin: 0 auto;\n}\n.cta-section h2 {\n    margin-bottom: 1rem;\n}\n.cta-subtitle {\n    margin-bottom: 2rem;\n}\n.cta-buttons {\n    display: flex;\n    gap: 1rem;\n    justify-content: center;\n    flex-wrap: wrap;\n}\n.cta-btn {\n    display: inline-block;\n    padding: 1rem 2rem;\n    border-radius: 6px;\n    text-decoration: none;\n    font-weight: 600;\n    transition: transform 0.2s, box-shadow 0.2s;\n}\n.cta-btn:hover {\n    transform: translateY(-2px);\n}\n.cta-btn-primary {\n    background: var(--color-white, #fff);\n    color: var(--color-primary, #1a1a2e);\n}\n.cta-btn-secondary {\n    background: transparent;\n    border: 2px solid var(--color-white, #fff);\n    color: var(--color-white, #fff);\n}\n@media (max-width: 768px) {\n    .cta-section { padding: 3rem 1.5rem; }\n    .cta-buttons { flex-direction: column; align-items: center; }\n    .cta-btn { width: 100%; max-width: 280px; text-align: center; }\n}\n</style>	{"headline": "string", "primary_cta": "string", "subheadline": "string", "secondary_cta": "string", "primary_cta_url": "string", "secondary_cta_url": "string"}	call-to-action	2025-11-21 16:50:06.407156+00	2026-02-20 13:11:50.830998+00	Call to Action		\N	\N	template	\N	\N	\N	\N	section	t	t	\N
