border-top: 1px solid rgba(255,255,255,0.1);\n    text-align: center;\n}\n.footer-bottom p {\n    margin: 0;\n    color: rgba(255,255,255,0.6);\n    font-size: 0.9rem;\n}\n@media (max-width: 768px) {\n    .footer-container {\n        grid-template-columns: 1fr 1fr;\n    }\n    .footer-brand {\n        grid-column: 1 / -1;\n    }\n}\n@media (max-width: 480px) {\n    .footer-container {\n        grid-template-columns: 1fr;\n    }\n}\n</style>	{"type": "object", "properties": {"year": {"type": "string"}, "tagline": {"type": "string"}, "logo_text": {"type": "string"}, "accent_color": {"type": "string", "default": "#16a085"}, "company_name": {"type": "string"}, "contact_email": {"type": "string"}, "primary_color": {"type": "string", "default": "#1a1a2e"}, "nav_items_html": {"type": "string"}}}	site-footer	2025-12-22 11:58:08.754997+00	2026-02-04 13:20:47.546716+00	Standard Footer	footer	["footer", "professional", "columns", "legal"]	\N	template	\N	\N	\N	\N	section	t	f	\N
