aec98dbe-76b7-4e13-9641-e5b6ba2502aa	head-seo-standard	Standard HTML head with SEO, Open Graph, and structured data support	<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>{{.title}}</title>\n    <meta name="description" content="{{.description}}">\n    {{if .keywords}}<meta name="keywords" content="{{.keywords}}">{{end}}\n\n    <!-- Open Graph -->\n    <meta property="og:title" content="{{if .og_title}}{{.og_title}}{{else}}{{.title}}{{end}}">\n    <meta property="og:description" content="{{if .og_description}}{{.og_description}}{{else}}{{.description}}{{end}}">\n    <meta property="og:type" content="{{if .og_type}}{{.og_type}}{{else}}website{{end}}">\n    {{if .canonical_url}}<meta property="og:url" content="{{.canonical_url}}">{{end}}\n    {{if .og_image}}<meta property="og:image" content="{{.og_image}}">{{end}}\n    <meta property="og:site_name" content="{{if .site_name}}{{.site_name}}{{else}}{{.company_name}}{{end}}">\n\n    <!-- Twitter Card -->\n    <meta name="twitter:card" content="summary_large_image">\n    <meta name="twitter:title" content="{{if .og_title}}{{.og_title}}{{else}}{{.title}}{{end}}">\n    <meta name="twitter:description" content="{{if .og_description}}{{.og_description}}{{else}}{{.description}}{{end}}">\n    {{if .og_image}}<meta name="twitter:image" content="{{.og_image}}">{{end}}\n\n    <!-- Canonical -->\n    {{if .canonical_url}}<link rel="canonical" href="{{.canonical_url}}">{{end}}\n\n    <!-- Theme Color -->\n    <meta name="theme-color" content="{{.primary_color}}">\n\n    <!-- Fonts -->\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n    {{if .font_url}}<link href="{{.font_url}}" rel="stylesheet">{{end}}\n\n    <!-- Theme CSS Variables -->\n    <style>\n        :root {\n            --primary: {{.primary_color}};\n            --secondary: {{.secondary_color}};\n            --accent: {{.accent_color}};\n            --text-dark: {{.text_color}};\n            --text-light: #666666;\n            --background: {{.background_color}};\n            --border: #e0e0e0;\n        }\n    </style>\n\n    {{if .theme_css}}\n    <style>\n        {{.theme_css}}\n    </style>\n    {{end}}\n\n    {{if .structured_data}}\n    <script type="application/ld+json">\n    {{.structured_data}}\n    </script>\n    {{end}}\n\n    {{if .analytics_id}}\n    <script async src="https://www.googletagmanager.com/gtag/js?id={{.analytics_id}}"></script>\n    <script>\n        window.dataLayer = window.dataLayer || [];\n        function gtag(){dataLayer.push(arguments);}\n        gtag('js', new Date());\n        gtag('config', '{{.analytics_id}}');\n    </script>\n    {{end}}\n\n    <link rel="stylesheet" href="/assets/css/styles.css">\n    <!-- Lucide Icons -->\n    <script src="https://unpkg.com/lucide@0.460.0/dist/umd/lucide.min.js"></script>\n    <script>document.addEventListener("DOMContentLoaded", function() { if (typeof lucide !== "undefined") { lucide.createIcons(); } });</script>\n</head>	{"type": "object", "properties": {"title": {"type": "string", "description": "Page title"}, "og_type": {"type": "string", "default": "website"}, "font_url": {"type": "string", "description": "Google Fonts URL (optional)"}, "keywords": {"type": "string", "description": "Meta keywords (optional)"}, "og_image": {"type": "string", "description": "OG image URL (optional)"}, "og_title": {"type": "string", "description": "Open Graph title (falls back to title)"}, "site_name": {"type": "string", "description": "Site name (falls back to company_name)"}, "theme_css": {"type": "string", "description": "Additional theme CSS"}, "text_color": {"type": "string", "default": "#333333"}, "description": {"type": "string", "description": "Meta description"}, "accent_color": {"type": "string", "default": "#16a085"}, "analytics_id": {"type": "string", "description": "Google Analytics ID (optional)