1b10c1e5-e505-4cbf-8324-55c5c4e94750	Features Grid	Grid of product/service features	<section class="features-section" data-component="features">\n    <div class="features-container">\n        <h2>{{.headline}}</h2>\n        {{if .subheadline}}<p class="features-subtitle">{{.subheadline}}</p>{{end}}\n        <div class="features-grid">\n            {{range .features}}\n            <div class="feature-item">\n                {{if .icon}}<div class="feature-icon"><i data-lucide="{{.icon}}"></i></div>{{end}}\n                <h3>{{.name}}</h3>\n                <p>{{.description}}</p>\n            </div>\n            {{end}}\n        </div>\n    </div>\n</section>\n<style>\n/* Layout only - colors inherited from global CSS */\n.features-section {\n    padding: var(--spacing-section, 5rem 2rem);\n}\n.features-container {\n    max-width: var(--container-max-width, 1200px);\n    margin: 0 auto;\n}\n.features-section h2 {\n    text-align: center;\n    margin-bottom: 1rem;\n}\n.features-subtitle {\n    text-align: center;\n    max-width: 600px;\n    margin: 0 auto 3rem;\n}\n.features-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n    gap: 2rem;\n}\n.feature-item {\n    text-align: center;\n    padding: 2rem;\n}\n.feature-icon {\n    width: 48px;\n    height: 48px;\n    margin: 0 auto 1rem;\n    color: var(--color-accent, #0f3460);\n}\n.feature-icon svg {\n    width: 100%;\n    height: 100%;\n}\n.feature-item h3 {\n    margin-bottom: 1rem;\n}\n.feature-item p {\n    margin: 0;\n}\n@media (max-width: 768px) {\n    .features-section { padding: 3rem 1.5rem; }\n    .features-grid { grid-template-columns: 1fr; gap: 1.5rem; }\n}\n</style>	{"features": [{"icon": "string", "name": "string", "description": "string"}], "headline": "string", "subheadline": "string"}	features	2025-11-21 16:50:06.398726+00	2026-02-04 20:13:32.230506+00	Features Grid		\N	\N	template	\N	\N	\N	\N	section	t	f	\N
b08af694-4c04-459d-aed8-7ad2fba93450	use-cases-list	Grid of use case items with title, client, summary and results	<section class="use-cases-section" data-component="use-cases-list">\n    <div class="use-cases-container">\n        <h2>{{.headline}}</h2>\n        {{if .subheadline}}<p class="use-cases-subtitle">{{.subheadline}}</p>{{end}}\n        <div class="use-cases-grid">\n            {{range .use_cases}}\n            <article class="use-case-item">\n                <h3>{{.title}}</h3>\n                <p class="use-case-client">{{.client}}</p>\n                <p>{{.summary}}</p>\n                {{if .results}}<p class="use-case-results"><strong>Results:</strong> {{.results}}</p>{{end}}\n            </article>\n            {{end}}\n        </div>\n    </div>\n</section>\n<style>\n.use-cases-section {\n    padding: var(--spacing-section, 5rem 2rem);\n    background: var(--color-surface, #f8f9fa);\n}\n.use-cases-container {\n    max-width: var(--container-max-width, 1200px);\n    margin: 0 auto;\n}\n.use-cases-section h2 {\n    text-align: center;\n    margin-bottom: 1rem;\n}\n.use-cases-subtitle {\n    text-align: center;\n    max-width: 600px;\n    margin: 0 auto 3rem;\n}\n.use-cases-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\n    gap: 2rem;\n}\n.use-case-item {\n    padding: 2rem;\n    background: var(--color-background, #fff);\n    border-radius: 8px;\n    box-shadow: 0 2px 8px rgba(0,0,0,0.06);\n}\n.use-case-item h3 {\n    margin-bottom: 0.5rem;\n}\n.use-case-client {\n    font-size: 0.9rem;\n    margin-bottom: 1rem;\n    color: var(--color-text-muted, #666);\n}\n.use-case-results {\n    margin-top: 1rem;\n    padding-top: 1rem;\n    border-top: 1px solid var(--color-border, #e2e8f0);\n}\n@media (max-width: 768px) {\n    .use-cases-section { padding: 3rem 1.5rem; }\n    .use-cases-grid { grid-template-columns: 1fr; }\n}\n</style>	{"headline": "string", "use_cases": [{"title": "string", "client": "string", "re