0197e8d7-1adc-43d6-ab32-d0716e013175	call_to_action	A prominent CTA section encouraging visitors to take the next step.	<section class="cta-section" data-component="call-to-action">\n    <div class="cta-container">\n        <h2>{{.headline}}</h2>\n        {{if .subheadline}}<p class="cta-subtitle">{{.subheadline}}</p>{{end}}\n        <div class="cta-buttons">\n            {{if .primary_cta}}\n            <a href="{{.primary_cta_url}}" class="cta-btn cta-btn-primary">{{.primary_cta}}</a>\n            {{end}}\n            {{if .secondary_cta}}\n            <a href="{{.secondary_cta_url}}" class="cta-btn cta-btn-secondary">{{.secondary_cta}}</a>\n            {{end}}\n        </div>\n    </div>\n</section>\n<style>\n.cta-section {\n    padding: var(--spacing-section, 5rem 2rem);\n    background: var(--color-primary, #1a1a2e);\n    color: var(--color-white, #fff);\n    text-align: center;\n\n    /* Dark section context */\n    --section-text: rgba(255,255,255,0.9);\n    --section-text-muted: rgba(255,255,255,0.85);\n    --section-heading: #ffffff;\n    --section-surface: rgba(255,255,255,0.05);\n    --section-border: rgba(255,255,255,0.2);\n}\n.cta-container {\n    max-width: 800px;\n    margin: 0 auto;\n}\n.cta-section h2 {\n    margin-bottom: 1rem;\n}\n.cta-subtitle {\n    margin-bottom: 2rem;\n}\n.cta-buttons {\n    display: flex;\n    gap: 1rem;\n    justify-content: center;\n    flex-wrap: wrap;\n}\n.cta-btn {\n    display: inline-block;\n    padding: 1rem 2rem;\n    border-radius: 6px;\n    text-decoration: none;\n    font-weight: 600;\n    transition: transform 0.2s, box-shadow 0.2s;\n}\n.cta-btn:hover {\n    transform: translateY(-2px);\n}\n.cta-btn-primary {\n    background: var(--color-white, #fff);\n    color: var(--color-primary, #1a1a2e);\n}\n.cta-btn-secondary {\n    background: transparent;\n    border: 2px solid var(--color-white, #fff);\n    color: var(--color-white, #fff);\n}\n@media (max-width: 768px) {\n    .cta-section { padding: 3rem 1.5rem; }\n    