086bb5e3-6816-44e3-a6c0-526aac0e4f0c	contact-form	Standard contact form with name, email, message fields	<section class="contact-form-section" data-component="contact-form">\n    <div class="contact-form-container">\n        <h2>{{.heading}}</h2>\n        {{if .subtitle}}<p class="contact-subtitle">{{.subtitle}}</p>{{end}}\n        <form class="contact-form" action="{{.form_action}}" method="POST">\n            <div class="form-group">\n                <label for="name">Name</label>\n                <input type="text" id="name" name="name" required>\n            </div>\n            <div class="form-group">\n                <label for="email">Email</label>\n                <input type="email" id="email" name="email" required>\n            </div>\n            <div class="form-group">\n                <label for="message">Message</label>\n                <textarea id="message" name="message" rows="5" required></textarea>\n            </div>\n            <button type="submit" class="form-submit">{{if .button_text}}{{.button_text}}{{else}}Send Message{{end}}</button>\n        </form>\n    </div>\n</section>\n<style>\n/* Layout only - colors inherited from global CSS */\n.contact-form-section {\n    padding: var(--spacing-section, 5rem 2rem);\n}\n.contact-form-container {\n    max-width: 600px;\n    margin: 0 auto;\n}\n.contact-form-section h2 {\n    text-align: center;\n    margin-bottom: 1rem;\n}\n.contact-subtitle {\n    text-align: center;\n    margin-bottom: 2rem;\n}\n.contact-form {\n    display: flex;\n    flex-direction: column;\n    gap: 1.5rem;\n}\n.form-group {\n    display: flex;\n    flex-direction: column;\n    gap: 0.5rem;\n}\n.form-group label {\n    font-weight: 500;\n}\n.form-group input,\n.form-group textarea {\n    padding: 0.75rem 1rem;\n    border: 1px solid var(--color-border, #e2e8f0);\n    border-radius: 6px;\n    font-family: inherit;\n    font-size: 1rem;\n    transition: border-color 0.2s, box-shadow 0.2s;\n}\n.form-group input:focus,\n.form-group textarea:focus {\n    outline: none;\n    border-color: var(--color-accent, #0f3460);\n    box-shadow: 0 0 0 3px rgba(15,52,96,0.1);\n}\n.form-submit {\n    padding: 1rem 2rem;\n    background: var(--color-accent, #0f3460);\n    color: var(--color-white, #fff);\n    border: none;\n    border-radius: 6px;\n    font-size: 1rem;\n    font-weight: 600;\n    cursor: pointer;\n    transition: background 0.2s, transform 0.2s;\n}\n.form-submit:hover {\n    transform: translateY(-2px);\n}\n@media (max-width: 768px) {\n    .contact-form-section { padding: 3rem 1.5rem; }\n}\n</style>	{"heading": "string", "form_action": "string", "submit_text": "string", "form_description": "string"}	contact-form	2026-01-15 15:56:05.77743+00	2026-02-03 17:39:30.142161+00	Contact Form	contact	["contact", "form", "lead-capture"]	\N	template	\N	\N	\N	\N	section	t	f	\N
