nt-size: 1rem;\n    transition: all 0.2s ease;\n}\n.hero .btn-primary {\n    background: var(--accent-color, #0f3460);\n    color: #fff;\n    border: 2px solid var(--accent-color, #0f3460);\n}\n.hero .btn-primary:hover {\n    background: transparent;\n    color: #fff;\n}\n.hero .btn-secondary {\n    background: transparent;\n    color: #fff;\n    border: 2px solid rgba(255,255,255,0.8);\n}\n.hero .btn-secondary:hover {\n    background: rgba(255,255,255,0.1);\n}\n@media (max-width: 768px) {\n    .hero {\n        min-height: 60vh;\n        padding: 3rem 1.5rem;\n    }\n    .hero .btn {\n        display: block;\n        width: 100%;\n        max-width: 280px;\n        margin: 0.5rem auto;\n    }\n}\n</style>	{"headline": "Transform Your Business Today", "primary_cta": "Get Started Now", "subheadline": "The ultimate solution for modern teams", "secondary_cta": "Learn More"}	hero	2025-11-21 16:50:06.394647+00	2026-02-20 13:11:50.835599+00	Hero Section		\N	\N	template	\N	\N	\N	\N	section	t	t	\N
